<script setup lang="ts">
import { useApi } from '~/composables/useApi';

import type { PriceHistory } from '~/types/api'
import { money,dateTR } from '~/utils/format'
const route=useRoute();const api=useApi();const id=String(route.params.id);const rows=ref<PriceHistory[]>([]);const state=ref<'loading'|'error'|'success'>('loading');const error=ref('')
async function load(){state.value='loading';try{rows.value=await api.priceHistory(id);state.value='success'}catch(e){error.value=e instanceof Error?e.message:'Fiyat geçmişi alınamadı.';state.value='error'}}
await load();const maxPrice=computed(()=>Math.max(1,...rows.value.map(r=>Number(r.asking_price))))
</script>
<template><div class="page-heading"><div><p class="eyebrow">PORTFÖY / FİYAT GÖZLEMLERİ</p><h1>İlan #{{ id }} · Fiyat geçmişi</h1><p>Sistemde kaydedilmiş fiyat kayıtları. İlk gözlem, gerçek ilk yayın fiyatı anlamına gelmez.</p></div><NuxtLink :to="`/listings/${id}`" class="button button-secondary">← İlan detayı</NuxtLink></div><section class="panel"><div class="panel-header"><div><h2>Kaydedilmiş fiyatlar</h2><p>Fiyatlar TL veya API'de kayıtlı para birimiyle gösterilir.</p></div><span class="chip">{{ rows.length }} gözlem</span></div><StatePanel v-if="state==='loading'" state="loading"/><StatePanel v-else-if="state==='error'" state="error" :message="error" @retry="load"/><StatePanel v-else-if="!rows.length" state="empty" message="Bu ilan için henüz fiyat geçmişi kaydı yok."/><template v-else><div class="chart-bars mb-16"><div v-for="r in rows" :key="r.id" class="chart-bar-row"><span class="chart-bar-label">{{ dateTR(r.recorded_at) }}</span><div class="chart-bar-track"><div class="chart-bar-fill" :style="{width:`${Number(r.asking_price)/maxPrice*100}%`}"/></div><span class="chart-bar-value">{{ money(r.asking_price,r.currency) }}</span></div></div><div class="table-wrap"><table><thead><tr><th>Kayıt</th><th>Fiyat</th><th>Para birimi</th><th>Tarih</th><th>Değişim türü</th><th>Kaydeden</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>#{{ r.id }}</td><td class="table-primary">{{ money(r.asking_price,r.currency) }}</td><td>{{ r.currency }}</td><td>{{ dateTR(r.recorded_at) }}</td><td>{{ r.change_reason }}</td><td>{{ r.recorded_by??'—' }}</td></tr></tbody></table></div></template><p class="panel-footnote">Bu kayıtlar ilan fiyatı gözlemleridir; gerçekleşmiş satış fiyatlarını temsil etmez.</p></section></template>
